theorem unnecessitation! : (Hilbert.GL ℕ) ⊢! □φ → (Hilbert.GL ℕ) ⊢! φ := by
  intro h;
  have : (Hilbert.GL ℕ) ⊢! □⊤ ➝ □φ := imply₁'! (ψ := □⊤) h;
  have : (Hilbert.GL ℕ) ⊢! ⊡⊤ ➝ φ := imply_boxdot_plain_of_imply_box_box this;
  exact this ⨀ boxdotverum!;

lemma truthlemma.lemma2
  {X : CCF (Hilbert.GL ℕ) φ.subformulae} (hq₁ : □ψ ∈ φ.subformulae) (hq₂ : □ψ ∉ X.formulae)
  : Formulae.Consistent (Hilbert.GL ℕ) ((X.formulae.prebox ∪ X.formulae.prebox.box) ∪ {□ψ, -ψ}) := by
  apply Formulae.intro_union_consistent;
  rintro Γ₁ Γ₂ ⟨hΓ₁, hΓ₂⟩;

  replace hΓ₂ : ∀ χ ∈ Γ₂, χ = □ψ ∨ χ = -ψ := by
    intro χ hr;
    simpa using hΓ₂ χ hr;

  by_contra hC;
  have : Γ₁ ⊢[_]! ⋀Γ₂ ➝ ⊥ := provable_iff.mpr $ and_imply_iff_imply_imply'!.mp hC;
  have : Γ₁ ⊢[_]! (□ψ ⋏ -ψ) ➝ ⊥ := imp_trans''! (by
    suffices Γ₁ ⊢[(Hilbert.GL ℕ)]! ⋀[□ψ, -ψ] ➝ ⋀Γ₂ by
      simpa only [ne_eq, List.cons_ne_self, not_false_eq_true, List.conj₂_cons_nonempty, List.conj₂_singleton];
    apply conjconj_subset!;
    simpa using hΓ₂;
  ) this;
  have : Γ₁ ⊢[_]! □ψ ➝ -ψ ➝ ⊥ := and_imply_iff_imply_imply'!.mp this;
  have : Γ₁ ⊢[(Hilbert.GL ℕ)]! □ψ ➝ ψ := by
    rcases Formula.complement.or (φ := ψ) with (hp | ⟨ψ, rfl⟩);
    . rw [hp] at this;
      exact imp_trans''! this dne!;
    . simpa only [complement] using this;
  have : (□'Γ₁) ⊢[_]! □(□ψ ➝ ψ) := contextual_nec! this;
  have : (□'Γ₁) ⊢[_]! □ψ := axiomL! ⨀ this;
  have : _ ⊢! ⋀□'Γ₁ ➝ □ψ := provable_iff.mp this;
  have : _ ⊢! ⋀□'(X.formulae.prebox ∪ X.formulae.prebox.box |>.toList) ➝ □ψ := imp_trans''! (conjconj_subset! (by
    suffices ∀ χ ∈ Γ₁, □χ ∈ X.formulae ∨ ∃ χ', □χ' ∈ X.formulae ∧ □χ' = χ by simpa;
    intro χ hr;
    simpa using hΓ₁ _ hr;
  )) this;
  have : _ ⊢! ⋀□'(X.formulae.prebox.toList) ➝ □ψ := imp_trans''! (conjconj_provable! (by
    suffices ∀ χ, (□χ ∈ X.formulae ∨ ∃ χ', □χ' ∈ X.formulae ∧ □χ' = χ) → (□'^[1](Finset.premultibox 1 X.formulae).toList) ⊢[Hilbert.GL ℕ]! □χ by simpa;
    rintro χ (hχ | ⟨χ, hχ, rfl⟩);
    . apply FiniteContext.by_axm!;
      simpa;
    . apply axiomFour'!;
      apply FiniteContext.by_axm!;
      simpa;
  )) this;
  have : X.formulae *⊢[(Hilbert.GL ℕ)]! □ψ := by
    apply Context.provable_iff.mpr;
    use □'X.formulae.prebox.toList;
    constructor;
    . simp;
    . assumption;
  have : □ψ ∈ X.formulae := membership_iff hq₁ |>.mpr this;
  contradiction;

lemma unprovable_AxiomT : (Hilbert.GL ℕ) ⊬ Axioms.T (.atom a) := by
  apply not_imp_not.mpr provable_CL_verTranslated;
  apply IntProp.Hilbert.Cl.unprovable_of_exists_classicalValuation;
  use (λ _ => False);
  simp [Axioms.T, VerTranslation, toPropFormula, IntProp.Formula.Kripke.Satisfies];

theorem provable_iff_satisfies_at_root_on_FiniteTransitiveTree : (Hilbert.GL ℕ) ⊢! φ ↔ (∀ M : FiniteTransitiveTreeModel, Satisfies M.toModel M.root φ) := by
  constructor;
  . intro h M;
    have : TransitiveIrreflexiveFiniteFrameClass ⊧ φ := Hilbert.GL.Kripke.finite_sound.sound h;
    have := valid_on_FiniteTransitiveTreeClass_of_valid_on_TransitiveIrreflexiveFrameClass this;
    exact satisfies_at_root_on_FiniteTransitiveTree this M;
  . intro h;
    apply Hilbert.GL.Kripke.complete.complete;
    intro F hF V;
    apply valid_on_TransitiveIrreflexiveFrameClass_of_satisfies_at_root_on_FiniteTransitiveTree h hF;

lemma unprovable_iff_exists_unsatisfies_at_root_on_FiniteTransitiveTree : (Hilbert.GL ℕ) ⊬ φ ↔ ∃ M : FiniteTransitiveTreeModel, ¬Satisfies M.toModel M.root φ := by
  apply Iff.not_left;
  push_neg;
  exact provable_iff_satisfies_at_root_on_FiniteTransitiveTree;

lemma imply_boxdot_plain_of_imply_box_box : (Hilbert.GL ℕ) ⊢! □φ ➝ □ψ → (Hilbert.GL ℕ) ⊢! ⊡φ ➝ ψ := by
  contrapose;
  intro h;
  have := Kripke.unprovable_iff_exists_unsatisfies_at_root_on_FiniteTransitiveTree.mp h;
  obtain ⟨M, hs⟩ := this;

  have hs : Satisfies M.toModel M.root (⊡φ ⋏ ∼ψ) := by simp_all [Satisfies, Semantics.Realize];
  replace hs := @SimpleExtension.modal_equivalence_original_world M M.root (⊡φ ⋏ ∼ψ) |>.mp hs;
  have ⟨hs₁₂, hs₃⟩ := Satisfies.and_def.mp hs;
  have ⟨hs₁, hs₂⟩ := Satisfies.and_def.mp hs₁₂;

  have hbp : Satisfies M↧.toModel (M↧.root) (□φ) := by
    intro x hx;
    rcases @Kripke.FiniteTransitiveTree.SimpleExtension.through_original_root M.toFiniteTransitiveTree x hx with (rfl | hr);
    . assumption;
    . apply hs₂;
      exact hr;
  have hbq : ¬(Satisfies M↧.toModel (M↧.root) (□ψ)) := by
    apply Satisfies.box_def.not.mpr;
    push_neg;
    use M.root;
    constructor;
    . apply M↧.toRootedFrame.root_rooted M.root;
      simp [SimpleExtension, Kripke.FiniteTransitiveTree.SimpleExtension]; -- TODO: extract lemma
    . assumption;

  apply Kripke.unprovable_iff_exists_unsatisfies_at_root_on_FiniteTransitiveTree.mpr;
  use M↧;
  exact _root_.not_imp.mpr ⟨hbp, hbq⟩;

